shared_html.shared_css:
/* ============================================================
   SHARED NAV + FOOTER — Tsukimi-tei
   Edo-Japanese, modern variant
   ============================================================ */

/* ---------- HEADER ---------- */

.site-nav {
  background: var(--bg);
  color: var(--text);
  padding: 2.4rem clamp(1.5rem, 4vw, 4rem) 0;
  font-family: 'Inter', system-ui, sans-serif;
}

.site-nav__inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: end;
  gap: 2rem;
  max-width: 1280px;
  margin: 0 auto;
}

.site-nav__mark {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: var(--primary);
  line-height: 1;
}

.site-nav__kanji {
  font-family: 'Shippori Mincho', serif;
  font-weight: 700;
  font-size: 2.1rem;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.site-nav__romaji {
  font-family: 'Inter', sans-serif;
  font-weight: 300;
  font-size: 0.72rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin-top: 0.55rem;
}

.site-nav__kicker {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.9rem;
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  font-weight: 300;
  padding-bottom: 0.5rem;
}

.site-nav__season {
  font-family: 'Shippori Mincho', serif;
  font-style: italic;
  letter-spacing: 0.18em;
  color: var(--accent);
  text-transform: none;
  font-size: 0.78rem;
}

.site-nav__sep {
  opacity: 0.4;
}

.site-nav__links ol {
  display: flex;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 1.6rem;
  justify-content: flex-end;
}

.site-nav__links a {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  text-decoration: none;
  color: var(--primary);
  padding-bottom: 0.4rem;
  border-bottom: 1px solid transparent;
  transition: border-color 0.3s ease, color 0.3s ease;
}

.site-nav__links .num {
  font-family: 'Shippori Mincho', serif;
  font-size: 0.85rem;
  color: var(--text-emphasis);
  opacity: 0.55;
  margin-bottom: 0.25rem;
}

.site-nav__links .lbl {
  font-size: 0.74rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 400;
}

.site-nav__links a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.site-nav__links a:hover .num {
  color: var(--accent);
  opacity: 1;
}

.site-nav__rule {
  max-width: 1280px;
  margin: 1.6rem auto 0;
  height: 1px;
  background: var(--ornament);
  opacity: 0.85;
}

@media (max-width: 820px) {
  .site-nav__inner {
    grid-template-columns: 1fr;
    gap: 1.2rem;
  }
  .site-nav__kicker { justify-content: flex-start; }
  .site-nav__links ol { flex-wrap: wrap; gap: 1rem; justify-content: flex-start; }
}

/* ---------- FOOTER ---------- */

.site-footer {
  background: var(--surface);
  color: var(--text);
  margin-top: 6rem;
  padding: 4rem clamp(1.5rem, 4vw, 4rem) 2.5rem;
  font-family: 'Inter', system-ui, sans-serif;
  border-top: 1px solid var(--ornament);
  position: relative;
}

.site-footer::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 100%;
  background-image: url('svg/asanoha-hempleaf.svg');
  background-size: 220px;
  background-repeat: repeat;
  opacity: 0.045;
  pointer-events: none;
}

.site-footer__inner {
  position: relative;
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: auto 1.4fr 1fr 1fr 1fr;
  gap: 2.5rem;
  align-items: start;
}

.site-footer__seal {
  width: 64px;
  height: 64px;
  color: var(--text-emphasis);
  margin-top: 0.2rem;
}

.site-footer__seal svg {
  width: 100%;
  height: 100%;
  display: block;
}

.site-footer__col h4 {
  font-family: 'Shippori Mincho', serif;
  font-weight: 500;
  font-size: 0.78rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin: 0 0 1rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid var(--ornament);
}

.site-footer__col p {
  font-size: 0.85rem;
  line-height: 1.85;
  margin: 0 0 0.7rem;
  font-weight: 300;
  color: var(--text);
}

.site-footer__col--mark .site-footer__name {
  font-family: 'Shippori Mincho', serif;
  font-weight: 700;
  font-size: 1.5rem;
  letter-spacing: 0.1em;
  color: var(--primary);
  margin-bottom: 0.4rem;
}

.site-footer__col--mark .site-footer__sub {
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin-bottom: 1.2rem;
}

.site-footer__col--mark .site-footer__line {
  font-family: 'Shippori Mincho', serif;
  font-style: italic;
  font-size: 0.95rem;
  color: var(--accent);
  letter-spacing: 0.04em;
}

.site-footer__nav {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0 2rem;
  padding: 2.4rem 0 1.4rem;
  margin-top: 1.5rem;
  border-top: 1px solid var(--ornament);
}

.site-footer__nav a {
  font-size: 0.74rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--primary);
  padding: 0.4rem 0;
  transition: color 0.3s ease;
}

.site-footer__nav a:hover { color: var(--accent); }

.site-footer__meta {
  grid-column: 1 / -1;
  text-align: center;
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--text);
  opacity: 0.7;
  line-height: 1.9;
}

.site-footer__meta p { margin: 0.2rem 0; }

.site-footer__attr {
  font-size: 0.65rem;
  opacity: 0.75;
  font-style: italic;
  letter-spacing: 0.06em;
}

@media (max-width: 980px) {
  .site-footer__inner {
    grid-template-columns: 1fr 1fr;
  }
  .site-footer__seal { grid-column: 1 / -1; }
  .site-footer__col--mark { grid-column: 1 / -1; }
}

@media (max-width: 560px) {
  .site-footer__inner { grid-template-columns: 1fr; }
  .site-footer__nav { gap: 0.7rem 1.4rem; }
}
